// === Tab: IsoCube.js ===
class IsoCube {
  constructor(parent = window) {
    // parent.
    this._pnt = parent;
    this.colors = ['red', 'green', 'blue'];
  }

  setColors(c1, c2, c3) {
    this.colors = [c1, c2, c3];
  }

  draw(centerX, centerY, size) {
    const p = this._pnt;
    p.push();
    {
      const o = createVector(0, 0);
      const vs = [0, 1, 2].map((i) => {
        return p5.Vector.fromAngle(PI / 2 + (i * TAU) / 3).mult(size);
      });

      [0, 1, 2].forEach((i) => {
        vs.push(vs[i].copy().add(vs[(i + 1) % 3]));
      });

      p.translate(centerX, centerY);
      [0, 1, 2].forEach((i) => {
        p.beginShape();
        {
          p.fill(this.colors[i]);
          p.vertex(o.x, o.y);
          p.vertex(vs[i].x, vs[i].y);
          p.vertex(vs[i + 3].x, vs[i + 3].y);
          p.vertex(vs[(i + 1) % 3].x, vs[(i + 1) % 3].y);
        }
        p.endShape(CLOSE);
      });
    }
    p.pop();
  }

  drawFrame(centerX, centerY, size) {
    const p = this._pnt;
    const o = createVector(centerX, centerY);
    const vs = [];

    vs.push(o);
    const v1 = p5.Vector.fromAngle(PI / 6).mult(size);
    const v3 = p5.Vector.fromAngle(PI / 6 + TAU / 3).mult(size);
    const v2 = v1.copy().add(v3);
    vs.push(v1.add(o));
    vs.push(v2.add(o));
    vs.push(v3.add(o));

    p.push();
    {
      p.noFill();
      p.beginShape();
      {
        vs.forEach((v) => {
          p.vertex(v.x, v.y);
        });
      }
      p.endShape(CLOSE);
    }
    p.pop();
  }
}

