// noprotect
const W = 720;

const unit = 10;
const numCubesRow = 40;
const startX = W / 2;
const startY = W / 4;

const bgColors = ['#f1e9db', '#5f3a11'];
const frameColor = 100;

let cellData = [];

// Color picking
const colsURL = 'https://coolors.co/ffbe0b-fb5607-ff006e-8338ec-3a86ff';
let colors = createCols(colsURL);

// Take some Colors from coolors URL
function createCols(url) {
  let slaIndex = url.lastIndexOf('/');
  let colStr = url.slice(slaIndex + 1);
  let colArr = colStr.split('-');
  for (let i = 0; i < colArr.length; i++) colArr[i] = '#' + colArr[i];
  return colArr;
}

let textureGfx;
const prepareTexture = () => {
  textureGfx = createGraphics(3 * W, 3 * W);
  textureGfx.noStroke();

  // White texture
  textureGfx.fill(255, 30);
  for (let i = 0; i < 200000; i++) {
    textureGfx.circle(random(3 * W), random(3 * W), (noise(i) * 3 * W) / (360 * 3));
  }

  // brown texture
  const c = color(bgColors[1]);
  c.setAlpha(20);
  textureGfx.fill(c);
  for (let i = 0; i < 200000; i++) {
    textureGfx.circle(random(3 * W), random(3 * W), (noise(i) * 3 * W) / 900);
  }
};

let frameGfx;

function setup() {
  createCanvas(W, W);

  frameRate(15);
  prepareTexture();
  shuffle(colors, true);

  strokeJoin(ROUND);

  // Create base cell data
  createCellData();

  // prepare frame graphics
  createFrame();

}

const createFrame = () => {
  frameGfx = createGraphics(W, W);
  frameGfx.stroke(frameColor);

  const ic = new IsoCube(frameGfx);

  for (let i = 0; i < numCubesRow; i++) {
    for (let j = 0; j < numCubesRow; j++) {
      const v = createVector(startX, startY);
      const vx = p5.Vector.fromAngle(PI - PI / 6).mult(j * unit);
      v.add(vx);
      const vy = p5.Vector.fromAngle(PI / 6).mult(i * unit);
      v.add(vy);
      ic.drawFrame(v.x, v.y, unit);
    }
  }
};

function draw() {
  background('#f1e9db');

  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
    scale(2);
    translate(W - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) * 2, W - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) * 2);
  }

  image(frameGfx, 0, 0, W, W);

  const ic = new IsoCube();
  ic.setColors(colors[0], colors[1], colors[2]);

  for (let i = 0; i < numCubesRow; i++) {
    for (let j = 0; j < numCubesRow; j++) {
      const v = createVector(startX, startY);
      const vx = p5.Vector.fromAngle(PI - PI / 6).mult(j * unit);
      v.add(vx);
      const vy = p5.Vector.fromAngle(PI / 6).mult(i * unit);
      v.add(vy);
      if (cellData[j][i] === 1) ic.draw(v.x, v.y, unit);
    }
  }

  image(textureGfx, -W, -W);

  updateCellData();
}

// Create cell data from image
const createCellData = () => {
  const columns = numCubesRow;
  const rows = numCubesRow;

  cellData = make2DArray(columns, rows);
  for (let i = 0; i < columns; i++) {
    for (let j = 0; j < rows; j++) {
      cellData[i][j] = floor(random(2));
    }
  }

  // console.log(cellData);
};

// Update cell data
const updateCellData = () => {
  const cols = numCubesRow;
  const rows = numCubesRow;
  const next = make2DArray(cols, rows);

  // Compute next based on cellData
  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      const state = cellData[i][j];

      // Count live neighbors!
      let neighbors = countNeighbours(cellData, i, j);

      if (state === 0 && neighbors === 3) {
        next[i][j] = 1;
      } else if (state === 1 && (neighbors < 2 || neighbors > 3)) {
        next[i][j] = 0;
      } else {
        next[i][j] = state;
      }
    }
  }

  cellData = next;
};

// Reference : "Coding Challenge #85: The Game of Life"
// https://youtu.be/FWSR_7kZuYg

const make2DArray = (cols, rows) => {
  let arr = new Array(cols);
  for (let i = 0; i < arr.length; i++) {
    arr[i] = new Array(rows);
  }

  return arr;
};

const countNeighbours = (data, x, y) => {
  let sum = 0;
  const cols = numCubesRow;
  const rows = numCubesRow;
  // console.log({cols, rows});

  for (let i = -1; i < 2; i++) {
    for (let j = -1; j < 2; j++) {
      let col = (cols + x + i) % cols;
      let row = (rows + y + j) % rows;

      sum += data[col][row];
    }
  }

  sum -= data[x][y];

  return sum;
};


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

